/**
 * AllDataTypes DataPills Validation - Part 3 of 11
 *
 * This file contains 15 ServiceNow datatypes for validation testing.
 * Each datatype is defined as a subflow input and referenced in a log action
 * to validate datapill functionality across all supported types.
 *
 * Datatypes in this part: days_of_week, decimal, document_id, documentation_field, domain_id...
 */

import { Subflow, wfa, action } from '@servicenow/sdk/automation'
import {
    DaysOfWeekColumn,
    DecimalColumn,
    DomainIdColumn,
    DomainPathColumn,
    DueDateColumn,
    EmailColumn,
    FieldListColumn,
    FieldNameColumn,
    GenericColumn,
    ReferenceColumn,
} from '@servicenow/sdk/core'

export const alldatatypesvalidationPart3 = Subflow(
    {
        $id: Now.ID['879ab5065989436cbe7e77de1da4424f'],
        name: 'AllDatatypesValidation_Part3',
        description: 'Comprehensive test subflow with ServiceNow datatypes - Part 3 of 11',
        runAs: 'user',
        inputs: {
            days_of_week: DaysOfWeekColumn({
                label: 'days_of_week',
                maxLength: 65000,
            }),
            decimal: DecimalColumn({
                label: 'decimal',
                maxLength: 65000,
            }),
            document_id: ReferenceColumn({
                label: 'document_id',
                referenceTable: 'sys_user',
            }),
            documentation_field: GenericColumn({
                label: 'documentation_field',
                maxLength: 80,
                columnType: 'documentation_field',
            }),
            domain_id: DomainIdColumn({
                label: 'domain_id',
            }),
            domain_path: DomainPathColumn({
                label: 'domain_path',
            }),
            due_date: DueDateColumn({
                label: 'due_date',
            }),
            dynamic_attribute_store: GenericColumn({
                label: 'dynamic_attribute_store',
                maxLength: 5000,
                columnType: 'dynamic_attribute_store',
            }),
            email: EmailColumn({
                label: 'email',
                maxLength: 65000,
            }),
            email_script: GenericColumn({
                label: 'email_script',
                maxLength: 65000,
                columnType: 'email_script',
            }),
            expression: GenericColumn({
                label: 'expression',
                columnType: 'expression',
            }),
            external_names: GenericColumn({
                label: 'external_names',
                maxLength: 65000,
                columnType: 'external_names',
            }),
            field_list: FieldListColumn({
                label: 'field_list',
                maxLength: 4000,
                dependent: 'inputs.field_name',
                hint: 'field_list dependent upon field_name',
            }),
            field_name: FieldNameColumn({
                label: 'field_name',
                maxLength: 65000,
            }),
            file_attachment: GenericColumn({
                label: 'file_attachment',
                maxLength: 65000,
                columnType: 'file_attachment',
            }),
        },
    },
    (_params) => {
        // Log action to validate all 15 datatypes in this part
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['57bb1b2d635348ed88d11d518da40c25'],
                annotation: 'Log DataTypes Group 3 - 15 datatypes',
                uuid: 'ce219278-6156-4ce7-af7d-96309a9fa794',
            },
            {
                log_level: 'info',
                log_message: `${wfa.dataPill(_params.inputs.days_of_week, 'days_of_week')} (days_of_week), ${wfa.dataPill(_params.inputs.decimal, 'decimal')} (Decimal), ${wfa.dataPill(_params.inputs.document_id, 'reference')} (Reference), ${wfa.dataPill(_params.inputs.documentation_field, 'documentation_field')} (documentation_field), ${wfa.dataPill(_params.inputs.domain_id, 'domain_id')} (domain_id), ${wfa.dataPill(_params.inputs.domain_path, 'domain_path')} (domain_path), ${wfa.dataPill(_params.inputs.due_date, 'due_date')} (due_date), ${wfa.dataPill(_params.inputs.dynamic_attribute_store, 'dynamic_attribute_store')} (dynamic_attribute_store), ${wfa.dataPill(_params.inputs.email, 'email')} (Email), ${wfa.dataPill(_params.inputs.email_script, 'email_script')} (email_script), ${wfa.dataPill(_params.inputs.expression, 'expression')} (Expression), ${wfa.dataPill(_params.inputs.external_names, 'external_names')} (external_names), ${wfa.dataPill(_params.inputs.field_list, 'field_list')} (field_list), ${wfa.dataPill(_params.inputs.field_name, 'field_name')} (field_name), ${wfa.dataPill(_params.inputs.file_attachment, 'file_attachment')} (file_attachment)`,
            }
        )
    }
)
